<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Orden de compra <?= html_escape(Almacen_compras_model::codigo($compra)) ?></title><link rel="stylesheet" href="<?= base_url() ?>assets/css/icons.css"><style>button{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:8px 12px;border:1px solid #ccc;border-radius:4px;background:#fff;font:14px Arial;cursor:pointer}button .mdi{font-size:18px}body{font:12px Arial;margin:24px}table{width:100%;border-collapse:collapse}th,td{padding:6px;border:1px solid #999}thead{display:table-header-group}thead th{text-align:left}tr{break-inside:avoid}.text-right{text-align:right;font-variant-numeric:tabular-nums}.font-weight-bold{font-weight:bold}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.compra-cliente{min-width:80px;overflow-wrap:anywhere}.compra-tabla-clientes td{white-space:nowrap}@media print{button{display:none}}<?php if($vista_clientes): ?>@page{size:A4 landscape}<?php endif; ?></style></head><body><button onclick="window.print()"><i class="mdi mdi-printer" aria-hidden="true"></i> Imprimir / PDF</button><h2>ORDEN DE COMPRA <?= html_escape(Almacen_compras_model::codigo($compra)) ?></h2><p>Proveedor: <?= html_escape($compra->proveedor) ?> · Estado: <?= html_escape(ucfirst($compra->estado)) ?></p><?php if($vista_clientes): ?><h3>SOLICITADO POR CLIENTE</h3><?php $this->load->view('almacen/compra_clientes',array('detalles'=>$detalles,'asignaciones'=>$asignaciones,'cantidades_clientes'=>$cantidades_clientes)); else: ?><table><thead><tr><th>Descripción</th><th>Unidad</th><th>Marca</th><th>Cantidad</th><th>Precio con IGV S/</th><th>Total S/</th></tr></thead><tbody><?php foreach($detalles as $d):if($d->cantidad<=0)continue; ?><tr><td><?= html_escape($d->descripcion) ?></td><td><?= html_escape($d->unidad) ?></td><td><?= html_escape($d->marca) ?></td><td class="text-right"><?= number_format($d->cantidad,3) ?></td><td class="text-right"><?= number_format($d->precio_real,2) ?></td><td class="text-right"><?= number_format($d->total,2) ?></td></tr><?php endforeach; ?><tr><th colspan="5" class="text-right">TOTAL DE COMPRA</th><th class="text-right"><?= number_format($compra->total,2) ?></th></tr></tbody></table><?php endif; ?><p><?= nl2br(html_escape($compra->observaciones)) ?></p></body></html>
